theorem tsum_Fterm_eq {N : ℕ} [NeZero N] (χ : DirichletCharacter ℂ N) (φ : ℝ → ℂ) {x : ℝ}
    (hx : 0 < x) (t : ℝ) : ∑' n : ℕ, (Λ n : ℂ) * χ n * Fterm φ x n t =
