def Approx2 (α x δ : ℝ) (a : ℤ) (q : ℕ) (Q₀ : ℝ) : Prop :=
  1 ≤ q ∧ IsCoprime a (q : ℤ) ∧ (∃ k : ℤ, 2 * α = a / q + δ / x + k) ∧
    |δ / x| ≤ 1 / (q * Q₀) ∧ (q : ℝ) ≤ Q₀

noncomputable def bound_4_52 (x δ : ℝ) (q : ℕ) (U V Q₀ ε : ℝ) : ℝ :=
  let D := U * V
  let c₁ := 1 + eta2'L1 / (x / D)
  let y := x / (|δ| * q)
  let Y := min ((⌊y⌋₊ : ℝ) + 1) (2 * D)
  2 * √(c₀ * c₁) / π * (D * Real.log (D / rexp 1) +
      (1 + ε) * Y * (√(3 + 2 * ε) * Real.log (5 * D) + 1 / 2 +
        (2 + Real.log D / 2) * logPlus (2 * D / y))) +
    3 * c₁ / 2 * (2 * Real.log (5 * D) + (1 + ε) / ε * Real.log D * logPlus (2 * D / y)) * (x / Q₀) +
    35 * c₀ * c₂ / (3 * π ^ 2) * q * Real.log D

theorem lemma_4_1_2 {α Q : ℝ} {a : ℤ} {q : ℕ} (h : Approx α a q Q) {y₁ y₂ : ℝ}
    (hy : 0 ≤ y₁) (_hy₁₂ : y₁ < y₂) (hlen : y₂ - y₁ ≤ q) (hy₂ : y₂ ≤ Q / 2) {A C : ℝ}
    (hA : 0 ≤ A) (hC : 0 ≤ C) :
    ∑ n ∈ Finset.Ioc ⌊y₁⌋ ⌊y₂⌋,
        (if (q : ℤ) ∣ n then 0 else min A (C / Real.sin (π * α * n) ^ 2)) ≤
      min (20 / (3 * π ^ 2) * C * q ^ 2) (2 * A + 4 * q / π * √(A * C)) :=

theorem norm_expTsum_le_of_chars {q : ℕ} [NeZero q] {c : ℕ → ℂ}
    (hc : Summable fun n => ‖c n‖) (β : ℝ) {b : ZMod q} (hb : IsUnit b) {M : ℂ} {E D : ℝ}
    (hD : ∑' n, ‖c n - coprimePart q c n‖ ≤ D)
    (hchar : ∀ ψ : DirichletCharacter ℂ q,
      ‖Schar ψ⁻¹.primitiveCharacter c β - (if ψ = 1 then M else 0)‖ ≤ E) :
    ‖expTsum c ((b.val : ℝ) / q + β)‖ ≤ D + ‖M‖ / q.totient + √q * (E + D) :=

theorem sum_G_le {q A C : ℝ} (hq : 0 < q) (hA : 0 ≤ A) (hC : 0 ≤ C) {u₁ : ℝ} {m : ℕ}
    (hu₁ : 1 ≤ u₁) (hlast : u₁ + m - 1 ≤ q / 2) :
    ∑ i ∈ Finset.range m, min A (C * fq q (u₁ + i)) ≤ 2 * (q / π) * √(A * C) :=

theorem sum_vonMangoldt_gcd_div_subset_le {q N : ℕ} (hq : 1 ≤ q) {s : Finset ℕ}
    (hs : s ⊆ Icc 1 N) :
    ∑ v ∈ s, (Λ v : ℝ) * (1 / v) * Nat.gcd q v ≤ ∑ v ∈ s, (Λ v : ℝ) * (1 / v) + Real.log q :=

